<?php

declare(strict_types=1);require_once __DIR__.'/../includes/auth.php';cmsRequireAuth();require_once __DIR__.'/../includes/csrf.php';require_once __DIR__.'/../includes/audit.php';require_once __DIR__.'/../includes/admin-ui.php';$pdo=cmsPdo();$id=(int)$_SESSION['cms_admin_id'];$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){cmsVerifyCsrf();$name=trim((string)($_POST['name']??''));$email=mb_strtolower(trim((string)($_POST['email']??'')));$current=(string)($_POST['current_password']??'');$new=(string)($_POST['new_password']??'');$s=$pdo->prepare('SELECT password_hash FROM admin_users WHERE id=:id');$s->execute([':id'=>$id]);$hash=(string)$s->fetchColumn();if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL))$error='راجع الاسم والبريد.';elseif(!password_verify($current,$hash))$error='كلمة المرور الحالية غير صحيحة.';elseif($new!==''&&strlen($new)<10)$error='كلمة المرور الجديدة يجب ألا تقل عن 10 أحرف.';else{try{$sql='UPDATE admin_users SET name=:n,email=:e'.($new!==''?',password_hash=:p':'').' WHERE id=:id';$q=$pdo->prepare($sql);$params=[':n'=>$name,':e'=>$email,':id'=>$id];if($new!=='')$params[':p']=password_hash($new,PASSWORD_DEFAULT);$q->execute($params);$_SESSION['cms_admin_name']=$name;$_SESSION['cms_admin_email']=$email;cmsAudit('account.update','admin_users',(string)$id);$message='تم تحديث الحساب.';}catch(PDOException $e){$error='تعذر الحفظ. تأكد أن البريد غير مستخدم.';}}}
$s=$pdo->prepare('SELECT name,email FROM admin_users WHERE id=:id');$s->execute([':id'=>$id]);$u=$s->fetch();cmsAdminHead('الحساب');cmsAdminSidebar('account');cmsAdminTopbar('الحساب');?>
<div class="content"><?php if($message):?><div class="alert success"><?=cmsE($message)?></div><?php endif;?><?php if($error):?><div class="alert error"><?=cmsE($error)?></div><?php endif;?><section class="card" style="max-width:760px"><form method="post"><?=cmsCsrfField()?><div class="form-grid"><label class="field"><span>الاسم</span><input name="name" required value="<?=cmsE((string)$u['name'])?>"></label><label class="field"><span>البريد</span><input type="email" name="email" required value="<?=cmsE((string)$u['email'])?>"></label><label class="field"><span>كلمة المرور الحالية</span><input type="password" name="current_password" required autocomplete="current-password"></label><label class="field"><span>كلمة مرور جديدة</span><input type="password" name="new_password" minlength="10" autocomplete="new-password" placeholder="اتركها فارغة لعدم التغيير"></label></div><button class="btn primary" style="margin-top:18px">حفظ</button></form></section></div><?php cmsAdminEnd();
